    const budget = (typeof VERIFICATION_COMMAND_BUDGET_MS === "number" ? VERIFICATION_COMMAND_BUDGET_MS : 15 * 60 * 1000) * 2;
    if (!(Number(run.at) > 0) || now - Number(run.at) >= budget) return false;
